import{_ as i,a as n,c as l,ac as o}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第二册：实践与进步 · 单元 1：把日常经历讲清楚","description":"L1–L24 的学习目标、课时入口和复习方法。","frontmatter":{"title":"第二册：实践与进步 · 单元 1：把日常经历讲清楚","description":"L1–L24 的学习目标、课时入口和复习方法。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","summary":"L1–L24 的学习目标、课时入口和复习方法。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 综合复习与自测 · 第91–96课","link":"/life/english/new-concept/book-2/review-part-11"},"next":{"text":"第二册：实践与进步 · 单元 1 语法总结","link":"/life/english/new-concept/book-2/unit-01/grammar"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 综合复习与自测 · 第91–96课","link":"/life/english/new-concept/book-2/review-part-11"},"next":{"text":"第二册：实践与进步 · 单元 1 语法总结","link":"/life/english/new-concept/book-2/unit-01/grammar"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/overview.md","filePath":"life/english/new-concept/book-2/unit-01/overview.md"}'),a={name:"life/english/new-concept/book-2/unit-01/overview.md"};function s(t,e,r,c,h,u){return n(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-单元-1-把日常经历讲清楚" tabindex="-1">第二册：实践与进步 · 单元 1：把日常经历讲清楚 <a class="header-anchor" href="#第二册-实践与进步-·-单元-1-把日常经历讲清楚" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 1：把日常经历讲清楚&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元复习与自测</a></p><h2 id="单元导读" tabindex="-1">单元导读 <a class="header-anchor" href="#单元导读" aria-label="Permalink to &quot;单元导读&quot;">​</a></h2><p>L1–L24。第1—24课从日常生活中的短小事件出发，把主语、动作、宾语和时间地点放进清楚的句子。学习重点不是一次记住所有术语，而是能区别习惯与单次事件、背景与转折、过去经历与当前结果。每课先观察原创例句，再完成变形和理解题，最后把同一结构迁移到自己的经历。单元结束时，应能不看范文写出一段有开头、经过和结果的小故事。</p><p>本栏目按连续课号组织学习单元；单元主题与复习任务为本站编排，便于分阶段学习，不作为各印次教材目录的替代。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>用正确语序讲述一次日常事件</li><li>区分现在、过去、进行和完成的基本视角</li><li>掌握常见冠词、情态动词及动词搭配</li></ul><h2 id="课时目录" tabindex="-1">课时目录 <a class="header-anchor" href="#课时目录" aria-label="Permalink to &quot;课时目录&quot;">​</a></h2><ul><li><a href="/life/english/new-concept/book-2/unit-01/lesson-001">Lesson 1 · A private conversation</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-002">Lesson 2 · Breakfast or lunch?</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-003">Lesson 3 · Please send me a card</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-004">Lesson 4 · An exciting trip</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-005">Lesson 5 · No wrong numbers</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-006">Lesson 6 · Percy Buttons</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-007">Lesson 7 · Too late</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-008">Lesson 8 · The best and the worst</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-009">Lesson 9 · A cold welcome</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-010">Lesson 10 · Not for jazz</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-011">Lesson 11 · One good turn deserves another</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-012">Lesson 12 · Goodbye and good luck</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-013">Lesson 13 · The Greenwood Boys</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-014">Lesson 14 · Do you speak English?</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-015">Lesson 15 · Good news</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-016">Lesson 16 · A polite request</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-017">Lesson 17 · Always young</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-018">Lesson 18 · He often does this!</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-019">Lesson 19 · Sold out</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-020">Lesson 20 · One man in a boat</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-021">Lesson 21 · Mad or not?</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-022">Lesson 22 · A glass envelope</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-023">Lesson 23 · A new house</a></li><li><a href="/life/english/new-concept/book-2/unit-01/lesson-024">Lesson 24 · It could be worse</a></li></ul><h2 id="单元知识地图" tabindex="-1">单元知识地图 <a class="header-anchor" href="#单元知识地图" aria-label="Permalink to &quot;单元知识地图&quot;">​</a></h2><ul><li>L1：一般过去时与事件顺序。quiet 是形容词，quietly 是副词；closed quiet 不能表达“轻轻合上”。</li><li>L2：一般现在时与习惯。He usually eat 不合主谓一致；He does usually eats 中不能重复标记第三人称单数。</li><li>L3：动词、宾语与补足语。send a postcard for her 表示替她寄，不一定表示寄给她；寄给她用 to her。</li><li>L4：现在完成时与过去时间。has visited yesterday 通常不合适；yesterday 明确结束的时间应配 visited。</li><li>L5：现在完成时与过去时间。receive 不等于 send；已收到用 have received，不要写 have receive。</li><li>L6：冠词与可数性。a bread 通常不能表示“一片面包”；用 a slice of bread，特定面包种类的用法另论。</li><li>L7：过去进行时与叙事背景。The guards was checking 主谓不一致；checking 是活动，不应以 checked 代替 -ing 来构成进行时。</li><li>L8：比较级与比较范围。Her garden is neater than me 比较对象不对称；用 than mine 或 than my garden。</li><li>L9：一般过去时与事件顺序。reach the square 不加 to；arrive at the square 才需要 at。</li><li>L10：被动语态与信息重点。The guitar was belonged to me 错误；belong 表归属，用 The guitar belonged to me。</li><li>L11：现在完成时与过去时间。borrow me a bicycle 通常不表示借给我；应说 lend me a bicycle。</li><li>L12：将来表达与安排。sail to the island 表示去岛上；sail across the island 不符合船只在水面航行的通常语境。</li><li>L13：将来进行时与过程。will rehearsing 缺少 be；will be rehearse 的动词形式也不对。</li><li>L14：过去进行时与叙事背景。explain me the route 不符合常见搭配；用 explain the route to me。</li><li>L15：间接引语与视角转换。said Hana that 错误；说给某人听可用 said to Hana 或 told Hana。</li><li>L16：情态动词的意义与形式。Could you to move 多了 to；could 是情态动词，后接原形。</li><li>L17：一般现在时与习惯。looks cheerfully 若没有其他内容不能表达“看起来愉快”；此处用 cheerful。</li><li>L18：一般现在时与习惯。Does the dog hides 错误；does 出现后使用 hide。</li><li>L19：情态动词的意义与形式。may to become 错误；情态动词后用原形，也不能把 may 解读成确定承诺。</li><li>L20：动名词与动词搭配。enjoy to fish 不是标准搭配；enjoy fishing 才表达喜欢钓鱼。</li><li>L21：被动语态与信息重点。noise 与 noisy 词性不同：traffic noise 是噪声，a noisy street 是吵闹的街道。</li><li>L22：动词、宾语与补足语。reply the message 通常应改为 reply to the message；answer the message 则不加 to。</li><li>L23：被动语态与信息重点。is building 表主动建造，不能让 footpath 像施工者一样行动；此处用 is being built。</li><li>L24：情态动词的意义与形式。someone 作主语按单数处理；someone have 应改为 someone has。</li></ul><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><p>能用自己的例子说明上面的语法点；能在不看答案时完成单元自测；能完成至少一项口头表达和一项书面表达，并根据课时点评修订。若做错，不必整单元重学，沿题目链接回到相应课时。</p>',13)])])}const g=i(a,[["render",s]]);export{d as __pageData,g as default};
